from gocardless_pro.services.base_service import BaseService

access_token = 'access-token-xyz'


@pytest.fixture
def client():
    return Client(access_token=access_token, base_url='http://example.com')


def idempotency_keys():
    return [call.request.headers['Idempotency-Key'] for call in responses.calls
            if call.request.method == 'POST']


def test_does_not_mutate_the_callers_headers():
    # The dict belongs to the caller. Leaving the generated key in it would make every later
    # create reuse that key.
    headers = {'Accept-Language': 'fr'}

    returned = BaseService(api_client=None)._inject_idempotency_key(headers)

    assert returned is not headers
    assert headers == {'Accept-Language': 'fr'}
    assert 'Idempotency-Key' in returned


def test_honours_an_explicit_idempotency_key():
    headers = {'Idempotency-Key': 'mine'}

    returned = BaseService(api_client=None)._inject_idempotency_key(headers)

    assert returned['Idempotency-Key'] == 'mine'
    assert headers == {'Idempotency-Key': 'mine'}


@responses.activate
def test_reused_headers_dict_gets_a_fresh_key_for_each_create(client):
    # Two independent creates sharing one non-empty headers dict, which is what a
    # module-level custom-header template looks like.
    responses.add(responses.POST, 'http://example.com/customers',
                  body=json.dumps({'customers': {'id': 'CU123'}}), status=201)
    responses.add(responses.POST, 'http://example.com/customers',
                  body=json.dumps({'customers': {'id': 'CU456'}}), status=201)
    shared_headers = {'Accept-Language': 'fr'}

    client.customers.create(params={'company_name': 'A'}, headers=shared_headers)
    client.customers.create(params={'company_name': 'B'}, headers=shared_headers)

    first, second = idempotency_keys()
    assert first != second
    assert shared_headers == {'Accept-Language': 'fr'}


@responses.activate
def test_key_is_stable_across_network_retries(client):
    # The key is generated once per call, so the API can recognise a retried request as the
    # same operation rather than a new one.
    responses.add(responses.POST, 'http://example.com/customers',
                  body=requests.exceptions.ConnectionError())
    responses.add(responses.POST, 'http://example.com/customers',
                  body=json.dumps({'customers': {'id': 'CU123'}}), status=201)

    client.customers.create(params={'company_name': 'A'},
                            headers={'Accept-Language': 'fr'})

    keys = idempotency_keys()
    assert len(keys) == 2
    assert keys[0] == keys[1]


@responses.activate
def test_conflict_refetch_does_not_forward_the_create_payload(client):
    # On a 409 the client refetches the conflicting resource. That is a GET for one resource,
    # so the create payload must not be carried into its query string.
    conflict = {'error': {'type': 'invalid_state', 'code': 409, 'message': 'Conflict',
                          'errors': [{'reason': 'idempotent_creation_conflict',
                                      'message': 'A resource has already been created',
                                      'links': {'conflicting_resource_id': 'CU123'}}]}}
    responses.add(responses.POST, 'http://example.com/customers',
                  body=json.dumps(conflict), status=409)
    responses.add(responses.GET, 'http://example.com/customers/CU123',
                  body=json.dumps({'customers': {'id': 'CU123'}}), status=200)

    customer = client.customers.create(params={'company_name': 'A', 'metadata': {'x': 'y'}},
                                       headers={'Accept-Language': 'fr'})

    assert customer.id == 'CU123'
    refetch = [call.request for call in responses.calls if call.request.method == 'GET'][0]
    assert refetch.url == 'http://example.com/customers/CU123'
